<script setup lang="ts">
import ServiceIntentList from '../components/ServiceIntentList.vue'
import {cloudApplications,intentMessagingEnabled,syncApplications} from '../services/remoteApplications'
import {cloudAuth} from '../services/cloudbase'
import {cloudProfiles,profileState,syncProfile,saveProfile} from '../services/remoteProfile'
import {cloudCommunity,cloudUnfollow,communityState,syncFollowerCount} from '../services/remoteCommunity'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {showConfirmDialog,showToast} from 'vant'
import {store,currentPets,image,compressImage} from '../stores/community'
import {clearLocalSession,updateLocalProfile} from '../services/auth'
import {supabase} from '../services/supabase'
import PostCard from '../components/PostCard.vue'
const router=useRouter(),panel=ref(''),editing=ref(false),nickname=ref(''),bio=ref(''),photo=ref(''),saving=ref(false),uploading=ref(false)
const serviceCenter=ref<HTMLElement|null>(null)
const mine=computed(()=>store.posts.filter(p=>p.mine)),liked=computed(()=>store.posts.filter(p=>p.liked)),receivedLikes=computed(()=>mine.value.reduce((sum,p)=>sum+p.likes,0))
const details=computed(()=>cloudProfiles?(profileState.ownerId===store.profile?.id?{photo:profileState.photo,bio:profileState.bio}:{photo:'',bio:''}):(store.profileDetails[store.profile?.email||'']||{photo:'',bio:''}))
const panels:Record<string,string>={posts:'我的发布',liked:'喜欢的动态',following:'我的关注',trips:'我的行程',buyer:'我找的服务',provider:'我提供的服务',settings:'账户设置',help:'帮助与说明'}
const serviceCard=(a:typeof store.applications[number])=>a.received
 ?(a.direction==='buyer'?'provider':'buyer')
 :a.direction
const applications=computed(()=>store.applications.filter(a=>serviceCard(a)===panel.value))
function pendingIntents(card:'provider'|'buyer',received:boolean){
 return store.applications.filter(a=>serviceCard(a)===card&&!!a.received===received&&a.status==='pending').length
}
const cancellationKey=computed(()=>store.profile?.id?`pawsup_seen_service_cancellations:${store.profile.id}`:'')
const seenCancellations=ref<string[]>([])
watch(cancellationKey,key=>{
 try{
  const saved=key?JSON.parse(localStorage.getItem(key)||'[]'):[]
  seenCancellations.value=Array.isArray(saved)?saved.filter(id=>typeof id==='string'):[]
 }catch{seenCancellations.value=[]}
},{immediate:true})
function unreadCancellations(card:'provider'|'buyer'){
 return store.applications.filter(a=>a.received&&a.status==='cancelled'
  &&serviceCard(a)===card&&!seenCancellations.value.includes(a.id))
}
function markCancellationsRead(card:'provider'|'buyer'){
 const ids=unreadCancellations(card).map(a=>a.id)
 if(!ids.length||!cancellationKey.value)return
 seenCancellations.value=[...seenCancellations.value,...ids]
 try{localStorage.setItem(cancellationKey.value,JSON.stringify(seenCancellations.value))}catch{}
}
watch([panel,()=>store.applications],([card], [previous])=>{
 if(card==='provider'||card==='buyer')markCancellationsRead(card)
 else if(previous==='provider'||previous==='buyer')markCancellationsRead(previous)
})
function refreshIntentUpdates(){
 if(cloudApplications&&document.visibilityState==='visible')void syncApplications().catch(()=>{})
}
function refreshProfileActivity(){
 void syncFollowerCount().catch(()=>{})
 refreshIntentUpdates()
}
let intentTimer:number|undefined
onMounted(()=>{
 refreshProfileActivity()
 window.addEventListener('focus',refreshProfileActivity)
 if(cloudApplications)intentTimer=window.setInterval(refreshIntentUpdates,20000)
})
onUnmounted(()=>{
 window.removeEventListener('focus',refreshProfileActivity)
 if(intentTimer!==undefined)window.clearInterval(intentTimer)
})
function edit(){if(cloudProfiles&&(profileState.error||profileState.loading)){showToast('请先刷新云端个人资料后重试');return}nickname.value=store.profile?.name||'';bio.value=details.value.bio;photo.value=details.value.photo;editing.value=true}
async function pick(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;uploading.value=true;try{photo.value=await compressImage(file)}catch(e){showToast((e as Error).message)}finally{uploading.value=false}}
async function save(){if(!store.profile||!nickname.value.trim()||uploading.value||saving.value)return;saving.value=true;try{if(cloudProfiles){await saveProfile({name:nickname.value,bio:bio.value,photo:photo.value})}else{store.profile={...store.profile,name:nickname.value.trim()};updateLocalProfile(store.profile);store.profileDetails[store.profile.email]={photo:photo.value,bio:bio.value.trim()}}editing.value=false;showToast(cloudProfiles?'资料已保存到云端':'资料已保存')}catch(e){showToast(e instanceof Error?e.message:'保存失败，请重试')}finally{saving.value=false}}
async function logout(){try{await showConfirmDialog({title:'退出登录',message:'退出后可以重新登录；云端宠物和帖子会保留。'});if(supabase){const {error}=await supabase.auth.signOut();if(error)throw error}else if(cloudAuth){await cloudAuth.signOut()}clearLocalSession();store.profile=null;router.replace('/auth')}catch(e){if(e instanceof Error)showToast(e.message)}}

async function unfollow(name:string){if(cloudCommunity){try{await cloudUnfollow(name)}catch(e){showToast((e as Error).message)}return}store.following=store.following.filter(a=>a!==name)}
</script>
<template><main class="my-page"><header class="my-top"><h1>我的</h1><div><button aria-label="查看服务留言" @click="serviceCenter?.scrollIntoView({behavior:'smooth'})"><van-icon name="bell"/></button><button aria-label="账户设置" @click="panel='settings'"><van-icon name="setting-o"/></button></div></header>
<p v-if="profileState.error" role="alert">个人资料加载失败：{{profileState.error}} <button @click="syncProfile(true).catch(()=>{})">刷新重试</button></p><p v-if="profileState.imageError" role="status">头像加载失败 <button @click="syncProfile(true).catch(()=>{})">重新加载</button></p><section class="my-profile"><div class="profile-overview"><button class="my-avatar" aria-label="编辑个人资料" @click="edit"><img :src="details.photo||currentPets[0]?.photo||image('pet-yunduo')" alt="我的头像"/><span><van-icon name="edit"/></span></button><div class="my-identity"><span class="my-eyebrow">MY LITTLE WORLD</span><h2>{{store.profile?.name||'铲屎官'}}</h2><p>{{details.bio||'和毛孩子一起，收藏生活的小美好。'}}</p><button @click="edit">编辑资料 <van-icon name="arrow"/></button></div></div><div class="my-badge"><span>🐾</span> 每一只，都值得被爱 <small>PawsUp 陪伴日常</small></div><div :class="['social-stats',{'with-followers':cloudCommunity}]"><button @click="panel='following'"><b>{{store.following.length}}</b><span>关注</span></button><div v-if="cloudCommunity"><b>{{communityState.followers??'—'}}</b><span>粉丝</span></div><button @click="panel='posts'"><b>{{mine.length}}</b><span>发布</span></button><button @click="panel='liked'"><b>{{liked.length}}</b><span>喜欢</span></button><div><b>{{receivedLikes}}</b><span>获赞</span></div></div></section>
<RouterLink to="/publish" class="my-publish"><span><van-icon name="edit"/> 记录今天的可爱</span><span>发布内容 <van-icon name="arrow"/></span></RouterLink>
<section><div class="my-section-head"><h2>我的宠物 <small>{{currentPets.length}} 位家庭成员</small></h2><RouterLink to="/pets">管理 ›</RouterLink></div><div class="my-pets" v-if="currentPets.length"><RouterLink v-for="pet in currentPets" :key="pet.id" to="/pets" class="my-pet"><img :src="pet.photo" :alt="pet.name"/><div><b>{{pet.name}}</b><small>{{pet.breed||pet.species}}</small><span>{{pet.age||'年龄待填写'}}</span></div></RouterLink><RouterLink class="add-pet" to="/pets"><van-icon name="plus"/><span>新增宠物</span></RouterLink></div><RouterLink v-else to="/pets" class="my-pets-empty"><span>🐾</span><div><b>给毛孩子一个专属的小天地</b><p>添加档案，记录每一段成长。</p></div><van-icon name="plus"/></RouterLink></section>
<section><div class="my-section-head"><h2>我的内容</h2><button @click="panel='liked'">喜欢的动态 ›</button></div><div class="content-tiles"><RouterLink to="/goods?saved=1" class="tile-pink"><van-icon name="like-o"/><span>收藏</span><b>{{store.savedProducts.length}}</b><small>喜欢的好物</small></RouterLink><button class="tile-blue" @click="panel='trips'"><van-icon name="calendar-o"/><span>行程</span><b>{{store.trips.length}}</b><small>出行小计划</small></button><button class="tile-yellow" @click="panel='posts'"><van-icon name="notes-o"/><span>发布</span><b>{{mine.length}}</b><small>分享的小日常</small></button></div></section>
<section ref="serviceCenter"><div class="my-section-head"><h2>服务中心</h2><span>{{cloudApplications?'云端意向记录':'本地意向记录'}}</span></div><div class="service-tiles"><button @click="panel='provider'"><span class="service-tile-icon provider"><van-icon name="service-o"/></span><div><b>我提供的服务<span v-if="unreadCancellations('provider').length" class="intent-cancel-dot" aria-label="有未读的取消通知"></span></b><p v-if="unreadCancellations('provider').length" class="intent-cancel-note">{{unreadCancellations('provider').length}} 条意向已被对方取消</p><p>{{pendingIntents('provider',true)}} 条收到咨询 · {{pendingIntents('provider',false)}} 条已发接单</p></div><van-icon name="arrow"/></button><button @click="panel='buyer'"><span class="service-tile-icon buyer"><van-icon name="orders-o"/></span><div><b>我找的服务<span v-if="unreadCancellations('buyer').length" class="intent-cancel-dot" aria-label="有未读的取消通知"></span></b><p v-if="unreadCancellations('buyer').length" class="intent-cancel-note">{{unreadCancellations('buyer').length}} 条意向已被对方取消</p><p>{{pendingIntents('buyer',true)}} 条收到接单 · {{pendingIntents('buyer',false)}} 条已发咨询</p></div><van-icon name="arrow"/></button></div><p class="service-caption">{{intentMessagingEnabled?'打开服务卡片查看意向和留言。':'打开服务卡片查看意向。'}}</p></section>
<section><div class="my-section-head"><h2>账户与服务</h2></div><div class="account-list"><button @click="panel='settings'"><span><van-icon name="setting-o"/>账户设置</span><span>资料与登录 <van-icon name="arrow"/></span></button><button @click="panel='help'"><span><van-icon name="question-o"/>帮助与说明</span><span>了解当前版本 <van-icon name="arrow"/></span></button><RouterLink to="/community"><span><van-icon name="friends-o"/>去社区逛逛</span><van-icon name="arrow"/></RouterLink></div></section><button class="my-logout" @click="logout">退出登录</button><footer>PAWSUP · 每一份陪伴，都值得记录。<br>宠物与社区云端同步 · 行程云端同步 · 服务意向云端记录</footer>
<van-popup :show="!!panel" @update:show="v=>{if(!v)panel=''}" round position="bottom" closeable><section class="my-panel"><h2>{{panels[panel]}}</h2><template v-if="panel==='posts'||panel==='liked'"><p class="panel-description">{{panel==='posts'?'你分享的每一刻，都在这里。':'把喜欢留给温暖的小日常。'}}</p><div class="masonry" v-if="(panel==='posts'?mine:liked).length"><PostCard v-for="p in (panel==='posts'?mine:liked)" :key="p.id" :post="p"/></div><van-empty v-else :description="panel==='posts'?'还没有发布内容':'还没有喜欢的动态'"/><RouterLink class="panel-link" :to="panel==='posts'?'/publish':'/community'" @click="panel=''">{{panel==='posts'?'发布新内容':'去社区发现可爱'}} ›</RouterLink></template>
<template v-else-if="panel==='following'"><p class="panel-description">当前关注 {{store.following.length}} 位社区作者</p><van-empty v-if="!store.following.length" description="还没有关注的朋友"/><article v-for="name in store.following" :key="name" class="follow-row"><img :src="store.posts.find(p=>(p.ownerId||p.author)===name)?.avatar||image('pet-yunduo')" :alt="name"/><span>{{communityState.authors[name]||name}}</span><button @click="unfollow(name)">取消关注</button></article><RouterLink class="panel-link" to="/community" @click="panel=''">去社区看看 ›</RouterLink></template>
<template v-else-if="panel==='trips'"><p class="panel-description">{{store.trips.length}} 份行程 · 场景路线示意</p><van-empty v-if="!store.trips.length" description="还没有行程，计划一次小出发吧"/><article v-for="trip in store.trips" :key="trip.id" class="panel-record"><span>{{trip.demoPets?'示例宠物行程':'出行计划'}}</span><h3>{{trip.city}} · {{trip.date}}</h3><p>{{trip.time}} 出发 · {{trip.petNames.join('、')}}</p><p>{{trip.stops.map(s=>s.title).join(' → ')}}</p></article><RouterLink class="panel-link" to="/outing" @click="panel=''">规划与管理行程 ›</RouterLink></template>
<template v-else-if="panel==='buyer'||panel==='provider'"><ServiceIntentList :items="applications" @navigate="panel=''"/><RouterLink class="panel-link" to="/community?section=service" @click="panel=''">去服务区看看 ›</RouterLink></template>
<template v-else-if="panel==='settings'"><p class="panel-description">管理个人资料和登录状态</p><div class="settings-account"><small>当前账号</small><b>{{store.profile?.email}}</b><span>{{cloudAuth?'CloudBase 身份认证':supabase?'Supabase 身份认证':'本地测试登录'}}</span></div><button class="settings-row" @click="panel='';edit()"><span>编辑资料</span><van-icon name="arrow"/></button><button class="settings-row danger" @click="logout">退出登录 <van-icon name="arrow"/></button><p class="panel-description">宠物、帖子和互动按云端账号保存；行程也按账号保存在云端；好物收藏与购物清单也已同步云端；服务意向也已同步云端，不构成订单。</p></template>
<template v-else-if="panel==='help'"><p class="panel-description">PawsUp 前端体验版</p><article class="help-block"><h3>现在可以体验什么？</h3><p>宠物档案、社区发布与互动、行程规划、好物收藏和购物清单。宠物和社区已接入云端；行程也已接入云端；好物收藏与购物清单也已接入云端。</p></article><article class="help-block"><h3>为什么没有订单和物流？</h3><p>服务意向与购物清单已同步云端，服务意向支持站内留言，预约、支付、库存和物流暂未接入。AI 助手暂时留空。</p></article><article class="help-block"><h3>换设备后能看到数据吗？</h3><p>登录同一账号可以读取云端宠物和帖子。行程也可跨设备同步；好物收藏与购物清单也可同步；个人资料也已同步；服务意向也支持跨设备查看。</p></article></template></section></van-popup>
<van-popup v-model:show="editing" round position="bottom" closeable><section class="my-panel edit-panel"><h2>编辑资料</h2><p class="panel-description">让邻居更好地认识你。</p><label class="edit-avatar"><img :src="photo||currentPets[0]?.photo||image('pet-yunduo')" alt="头像预览"/><span><van-icon name="photograph"/></span><input type="file" aria-label="更换头像" accept="image/jpeg,image/png,image/webp" :disabled="uploading" @change="pick"/></label><p class="avatar-hint">{{uploading?'正在处理图片…':'点击更换头像 · 自动压缩'}}</p><van-form @submit="save"><van-field v-model="nickname" label="昵称" maxlength="24" placeholder="怎么称呼你" :rules="[{validator:v=>!!v.trim(),message:'请填写昵称'}]"/><van-field v-model="bio" label="个人简介" type="textarea" maxlength="100" show-word-limit rows="3" placeholder="聊聊你和毛孩子的小日常"/><van-button block round native-type="submit" :loading="saving" :disabled="uploading" color="linear-gradient(120deg,#e68068,#d0614e)">保存资料</van-button></van-form><p class="panel-description">{{supabase?'昵称、头像和简介保存在云端，社区用户可见；登录邮箱不变。':'头像与简介保存在本机；登录账号不受昵称修改影响。'}}</p></section></van-popup></main></template>
<style scoped>
.intent-cancel-dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:#d8494a;margin-left:7px;vertical-align:middle}
.service-tiles .intent-cancel-note{color:#b43b3d;font-weight:650}

.social-stats.with-followers{grid-template-columns:repeat(5,minmax(0,1fr))}

